const jobs = inputs.map((item, index) => {
  const job = item.json || {};
  const creativeId = text(job.creative_id);
  if (!creativeId) throw new Error(`Creative ID ausente no job ${job.job_key || index}.`);
  const action = text(job.action);
  if (!['create_new', 'replace_existing'].includes(action)) throw new Error(`Acao invalida no job ${job.job_key || index}.`);
  const target = action === 'replace_existing'
    ? `ad:${text(job.source_ad_id)}`
    : `adset:${text(job.destination_adset_id)}:name:${key(object(job.adPayload).name)}`;
  if (targets.has(target)) throw new Error(`Target Meta duplicado no mesmo lote: ${target}`);
  targets.add(target);
  const adPayload = {
    ...object(job.adPayload),
    status: 'PAUSED',
    creative: { creative_id: creativeId },
  };
  return {
    operation_key: key(`ad:${runId}:${job.creative_group_key}:${job.destination_group}`),
    action,
    target_ad_id: action === 'replace_existing' ? text(job.source_ad_id) : undefined,
    token_id: text(job.token_id),
    account_id: text(job.account_id),
    api_version: text(job.api_version || 'v25.0'),
    destination_group: text(job.destination_group),
    creative_group_key: text(job.creative_group_key || job.group_key),
    creative_id: creativeId,
    ad_payload: adPayload,
    files: Object.entries(object(job.asset_ids)).map(([ratio, id]) => ({
      id: text(id),
      ratio: text(ratio),
      name: text(object(job.asset_names)[ratio]),
    })).filter((file) => file.id),
  };
});

return [{
  json: {
    run_id: runId,
    stage_operation_key: key(`stage:${runId}`),
    gateway_request: {
      action: 'stage_batch',
      operation_key: key(`stage:${runId}`),
      jobs,
    },
    job_count: jobs.length,
  },
}];

function text(value) { return String(value ?? '').trim(); }
function key(value) { return text(value).normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^A-Za-z0-9_.:-]+/g, '_').slice(0, 190); }

const response = $input.first()?.json || {};
if (response.ok !== true || response.operation?.status !== 'completed' || response.operation?.result?.status !== 'staged') {
  throw new Error(`Stage Ad Batch nao concluiu com seguranca: ${JSON.stringify(response.detail || response.error || response)}`);
}
const stageRequest = $items('Build Stage Batch')[0]?.json || {};
const runId = text(stageRequest.run_id);
const stageOperationKey = text(response.operation.operation_key || stageRequest.stage_operation_key);
if (!runId || !stageOperationKey) throw new Error('Build Activate Batch sem run_id ou stage_operation_key.');

return [{
  json: {
    run_id: runId,
    stage_operation_key: stageOperationKey,
    gateway_request: {
      action: 'activate_batch',
      operation_key: key(`activate:${runId}`),
      stage_operation_key: stageOperationKey,
    },
  },
}];

function text(value) { return String(value ?? '').trim(); }
function list(value) { return Array.isArray(value) ? value : []; }
function unique(values) { return [...new Set(list(values).map(text).filter(Boolean))]; }

const input = $input.first()?.json || {};
let runId = text(input.run_id);
let jobs = [];
if (input.resume_drive_only === true) {
  runId = text(input.run_id || input.run?.id);
  jobs = list(input.run?.summary?.jobs);
} else {
  if (input.ok !== true || input.operation?.status !== 'completed') {
    throw new Error(`Activate Ad Batch falhou: ${JSON.stringify(input.detail || input.error || input)}`);
  }
  const result = input.operation.result || {};
  if (result.status !== 'meta_completed_drive_pending') {
    throw new Error(`Activate Ad Batch retornou estado inesperado: ${JSON.stringify(result)}`);
  }
  runId = text(($items('Build Activate Batch')[0]?.json || {}).run_id);
  jobs = list(result.jobs);
}
if (!runId || !jobs.length) throw new Error('Build Drive Finalization sem run_id ou jobs persistidos.');

const byFile = new Map();
for (const job of jobs) {
  for (const file of list(job.files)) {
    const id = text(file.id);
    if (!id) continue;
    if (!byFile.has(id)) byFile.set(id, { id, name: text(file.name), ratio: text(file.ratio), units: [], ad_ids: [], creative_ids: [], groups: [] });
    const row = byFile.get(id);
    row.units.push(job.destination_group);
    row.ad_ids.push(job.ad_id);
    row.creative_ids.push(job.creative_id);
    row.groups.push(job.creative_group_key);
  }
}
if (!byFile.size) throw new Error('Build Drive Finalization nao recuperou os arquivos do journal.');

const publishedAt = new Date().toISOString();
const summaries = jobs.map((job) => ({
  creative_group_key: text(job.creative_group_key),
  destination_group: text(job.destination_group),
  action: text(job.action),
  ad_id: text(job.ad_id),
  creative_id: text(job.creative_id),
  created_new: job.created_new === true,
}));
const lines = [
  'Meta Ads Publish concluido',
  `Run: ${runId}`,
  `Jobs Meta: ${summaries.length}`,
  `Artes: ${byFile.size}`,
  '',
  ...summaries.map((job) => `- ${job.creative_group_key} | ${job.destination_group} | ${job.action} | ad ${job.ad_id}`),
];
const message = lines.join('\n');

return [...byFile.values()].map((file) => ({
  json: {
    id: file.id,
    fileName: file.name,
    ratio: file.ratio,
    run_id: runId,
    published: true,
    meta_ads_published_at: publishedAt,
    meta_ads_execution_id: String($execution.id),
    meta_ads_run_id: runId,
    meta_ads_creative_group_key: unique(file.groups).join(', '),
    meta_ads_units: unique(file.units).join(', '),
    meta_ads_ad_ids: unique(file.ad_ids).join(', '),
    meta_ads_creative_ids: unique(file.creative_ids).join(', '),
    meta_publish_summary: summaries,
    whatsapp_message: message,
    telegram_message: message,
  },
}));

function pairedIndex(item, fallback) {
  const paired = item && item.pairedItem;
  if (Array.isArray(paired) && paired.length) return Number(paired[0].item ?? fallback);
  if (paired && typeof paired === 'object') return Number(paired.item ?? fallback);
  return Number(fallback);
}

const expected = $items('Build Drive Finalization') || [];
return $input.all().map((item, index) => {
  const sourceIndex = pairedIndex(item, index);
  const source = (expected[sourceIndex] || {}).json || {};
  return {
    json: {
      ...source,
      drive_update_response: item.json || {},
      drive_update_had_error: Boolean(item.json && item.json.error),
    },
    pairedItem: { item: sourceIndex },
  };
});

function text(value) { return String(value ?? '').trim(); }
function pairedIndex(item, fallback) {
  const paired = item && item.pairedItem;
  if (Array.isArray(paired) && paired.length) return Number(paired[0].item ?? fallback);
  if (paired && typeof paired === 'object') return Number(paired.item ?? fallback);
  return Number(fallback);
}

const prepared = $items('Prepare Drive Read') || [];
const verified = [];
for (const [index, item] of $input.all().entries()) {
  const sourceIndex = pairedIndex(item, index);
  const expected = (prepared[sourceIndex] || {}).json || {};
  const actual = item.json || {};
  const properties = actual.properties || {};
  const checks = {
    published: text(properties.published) === 'true',
    run_id: text(properties.meta_ads_run_id) === text(expected.run_id),
    groups: text(properties.meta_ads_creative_group_key) === text(expected.meta_ads_creative_group_key),
  };
  if (!checks.published || !checks.run_id || !checks.groups) {
    throw new Error(`Drive readback falhou para ${expected.id}: ${JSON.stringify(checks)}`);
  }
  verified.push(expected);
}
if (verified.length !== prepared.length) throw new Error(`Drive readback incompleto: ${verified.length}/${prepared.length}.`);

const first = verified[0];
return [{
  json: {
    run_id: text(first.run_id),
    verified_file_count: verified.length,
    files: verified.map((item) => ({ id: text(item.id), name: text(item.fileName) })),
    meta_publish_summary: first.meta_publish_summary,
    whatsapp_message: text(first.whatsapp_message),
    telegram_message: text(first.telegram_message),
    completion_request: {
      status: 'completed',
      summary: {
        verified_file_count: verified.length,
        jobs: first.meta_publish_summary,
      },
    },
  },
}];

function text(value) { return String(value ?? '').trim().toLowerCase(); }
function list(value) { return Array.isArray(value) ? value : []; }
function object(value) { return value && typeof value === 'object' && !Array.isArray(value) ? value : {}; }
function values(targeting, configuredKey, effectiveKey) {
  const effective = list(targeting[effectiveKey]).map(text).filter(Boolean);
  return effective.length ? effective : list(targeting[configuredKey]).map(text).filter(Boolean);
}
function includesAny(actual, expected) { return expected.some((value) => actual.includes(value)); }
function missing(actual, expected) { return expected.filter((value) => !actual.includes(value)); }

const failures = [];
const outputs = [];
for (const item of $input.all()) {
  const root = object(item.json);
  if (root.ok !== true) throw new Error(`Meta placement preflight sem inventario valido: ${JSON.stringify(root.error || root.detail || {})}`);
  const checks = list(root.placement_checks);
  if (!checks.length) throw new Error('Meta placement preflight nao recebeu adsets para validar.');
  const normalizedChecks = [];

  for (const entry of checks) {
    const targeting = object(entry && entry.targeting);
    const publishers = values(targeting, 'publisher_platforms', 'effective_publisher_platforms');
    const facebook = values(targeting, 'facebook_positions', 'effective_facebook_positions');
    const instagram = values(targeting, 'instagram_positions', 'effective_instagram_positions');
    const audienceNetwork = values(targeting, 'audience_network_positions', 'effective_audience_network_positions');
    const whatsapp = values(targeting, 'whatsapp_positions', 'effective_whatsapp_positions');
    const problems = [];

    problems.push(...missing(publishers, ['facebook', 'instagram', 'audience_network', 'whatsapp']).map((value) => `publisher:${value}`));
    if (!includesAny(facebook, ['instream_video', 'instream_reel'])) problems.push('facebook:instream_video');
    if (!facebook.includes('story')) problems.push('facebook:story');
    if (!includesAny(facebook, ['facebook_reels', 'fb_reels'])) problems.push('facebook:facebook_reels');
    if (!facebook.includes('feed')) problems.push('facebook:feed');
    if (!facebook.includes('search')) problems.push('facebook:search');
    problems.push(...missing(instagram, ['story', 'reels']).map((value) => `instagram:${value}`));
    if (!audienceNetwork.includes('classic')) problems.push('audience_network:classic');
    if (!whatsapp.some((value) => value.includes('status'))) problems.push('whatsapp:status');

    if (problems.length) {
      failures.push({
        destination_group: String(entry && entry.destination_group || ''),
        adset_id_present: Boolean(String(entry && entry.adset_id || '')),
        missing_effective_placements: problems,
      });
    }

    normalizedChecks.push({
      ...entry,
      advantage_plus_eligibility: {
        instagram_static_image_music: publishers.includes('instagram') && includesAny(instagram, ['story', 'reels', 'stream']),
        effective_instagram_positions: instagram,
        effective_publisher_platforms: publishers,
      },
    });
  }

  outputs.push({
    ...item,
    json: {
      ...root,
      placement_checks: normalizedChecks,
      placement_preflight: {
        status: 'ok',
        checked_adsets: checks.length,
        required_vertical_crop: '90x160',
        required_horizontal_crop: '191x100',
        required_horizontal_placement: 'facebook:search',
      },
    },
  });
}

if (failures.length) {
  throw new Error(`Meta placement preflight bloqueou o lote: ${JSON.stringify(failures)}`);
}

return outputs;

function text(value) {
  return String(value ?? '').trim();
}

function clone(value) {
  return value == null ? value : JSON.parse(JSON.stringify(value));
}

const inputItems = $input.all();
if (!inputItems.length) {
  throw new Error('Prepare Visual Grouping Batch recebeu zero imagens.');
}

const images = [];
const binary = {};
const seenDriveIds = new Set();

for (const [itemIndex, item] of inputItems.entries()) {
  const source = item?.json || {};
  const driveId = text(source.id);
  const entries = Object.entries(item?.binary || {}).filter(([, value]) =>
    text(value?.mimeType).toLowerCase().startsWith('image/')
  );

  if (!driveId) {
    throw new Error(`Imagem ${itemIndex + 1} sem id do Google Drive.`);
  }
  if (seenDriveIds.has(driveId)) {
    throw new Error(`Imagem duplicada no lote visual: ${driveId}.`);
  }
  if (entries.length !== 1) {
    throw new Error(`Arquivo ${driveId} precisa conter exatamente um binario de imagem; encontrados ${entries.length}.`);
  }

  seenDriveIds.add(driveId);
  const [, binaryData] = entries[0];
  const ordinal = images.length + 1;
  const imageRef = `IMG_${String(ordinal).padStart(3, '0')}`;
  const binaryKey = `image_${String(ordinal).padStart(3, '0')}`;

  images.push({
    image_ref: imageRef,
    ordinal,
    drive_id: driveId,
    binary_key: binaryKey,
    mime_type: text(binaryData.mimeType || source.mimeType),
    source_json: clone(source),
  });
  binary[binaryKey] = clone(binaryData);
}

return [{
  json: {
    visual_grouping_batch_version: '1',
    input_count: images.length,
    images,
  },
  binary,
}];

function text(value) {
  return String(value ?? '').trim();
}

function list(value) {
  return Array.isArray(value) ? value : [];
}

function object(value) {
  return value && typeof value === 'object' && !Array.isArray(value) ? value : {};
}

function clone(value) {
  return value == null ? value : JSON.parse(JSON.stringify(value));
}

function parseObject(value) {
  if (value && typeof value === 'object' && !Array.isArray(value)) return value;
  if (typeof value !== 'string' || !value.trim()) return null;
  try {
    const parsed = JSON.parse(value);
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : null;
  } catch {
    return null;
  }
}

function unwrapAgent(value) {
  const root = object(value);
  const direct = parseObject(root.output);
  if (direct) return direct.output && typeof direct.output === 'object' ? direct.output : direct;
  return root.output && typeof root.output === 'object' ? root.output : root;
}

const prepared = ($items('Prepare Visual Grouping Batch') || [])[0];
const manifest = list(prepared?.json?.images);
const preparedBinary = prepared?.binary || {};
if (!manifest.length) {
  throw new Error('Validate Visual Grouping nao encontrou o manifesto original.');
}

const agentItem = $input.first();
const result = unwrapAgent(agentItem?.json || {});
const groups = list(result.groups);
const assignments = list(result.assignments);
if (!groups.length || !assignments.length) {
  throw new Error(`Agente visual retornou estrutura vazia: ${JSON.stringify(result).slice(0, 1000)}`);
}

const groupByKey = new Map();
for (const rawGroup of groups) {
  const group = object(rawGroup);
  const key = text(group.group_key).toUpperCase();
  if (!/^VISUAL_GROUP_[0-9]{2,}$/.test(key)) {
    throw new Error(`Chave de grupo visual invalida: ${text(group.group_key)}.`);
  }
  if (groupByKey.has(key)) throw new Error(`Grupo visual duplicado: ${key}.`);
  groupByKey.set(key, {
    group_key: key,
    visual_concept: text(group.visual_concept),
    confidence: Number(group.confidence),
    evidence: list(group.evidence).map(text).filter(Boolean),
  });
}

const manifestByRef = new Map(manifest.map((entry) => [text(entry.image_ref), entry]));
const assignmentByRef = new Map();
const supportedRatios = new Set(['1x1', '2x1', '3x4', '4x5', '9x16']);
const slotForRatio = (ratio) => ratio === '2x1' ? 'banner' : ratio === '9x16' ? 'stories' : 'feed';

for (const rawAssignment of assignments) {
  const assignment = object(rawAssignment);
  const imageRef = text(assignment.image_ref);
  const groupKey = text(assignment.group_key).toUpperCase();
  const ratio = text(assignment.ratio).toLowerCase();
  const slot = text(assignment.slot).toLowerCase();

  if (!manifestByRef.has(imageRef)) throw new Error(`Agente visual retornou referencia desconhecida: ${imageRef}.`);
  if (assignmentByRef.has(imageRef)) throw new Error(`Imagem atribuida mais de uma vez: ${imageRef}.`);
  if (!groupByKey.has(groupKey)) throw new Error(`Imagem ${imageRef} referencia grupo inexistente: ${groupKey}.`);
  if (!supportedRatios.has(ratio)) throw new Error(`Proporcao visual nao suportada para ${imageRef}: ${ratio}.`);
  if (slotForRatio(ratio) !== slot) throw new Error(`Slot ${slot} incompativel com proporcao ${ratio} em ${imageRef}.`);

  const confidence = Number(assignment.confidence);
  if (!Number.isFinite(confidence) || confidence < 0 || confidence > 1) {
    throw new Error(`Confianca invalida para ${imageRef}: ${assignment.confidence}.`);
  }

  assignmentByRef.set(imageRef, {
    image_ref: imageRef,
    group_key: groupKey,
    ratio,
    slot,
    confidence,
    evidence: list(assignment.evidence).map(text).filter(Boolean),
  });
}

const missing = [...manifestByRef.keys()].filter((ref) => !assignmentByRef.has(ref));
if (missing.length || assignmentByRef.size !== manifestByRef.size) {
  throw new Error(`Agrupamento visual nao cobriu o lote exatamente uma vez. missing=${JSON.stringify(missing)} expected=${manifestByRef.size} assigned=${assignmentByRef.size}`);
}

for (const groupKey of groupByKey.keys()) {
  const groupAssignments = [...assignmentByRef.values()].filter((entry) => entry.group_key === groupKey);
  const slots = groupAssignments.map((entry) => entry.slot);
  const missingSlots = ['feed', 'banner', 'stories'].filter((slot) => !slots.includes(slot));
  const duplicateSlots = [...new Set(slots.filter((slot, index) => slots.indexOf(slot) !== index))];
  if (missingSlots.length || duplicateSlots.length || groupAssignments.length !== 3) {
    throw new Error(`Grupo visual incompleto ou ambiguo ${groupKey}. missing_slots=${JSON.stringify(missingSlots)} duplicate_slots=${JSON.stringify(duplicateSlots)} images=${groupAssignments.length}`);
  }
}

const outputs = [];
for (const entry of manifest) {
  const imageRef = text(entry.image_ref);
  const assignment = assignmentByRef.get(imageRef);
  const group = groupByKey.get(assignment.group_key);
  const binaryData = preparedBinary[text(entry.binary_key)];
  if (!binaryData) throw new Error(`Binario original ausente para ${imageRef}.`);

  outputs.push({
    json: {
      ...clone(object(entry.source_json)),
      visual_grouping: {
        version: '1',
        strategy: 'ai_visual_global',
        image_ref: imageRef,
        group_key: assignment.group_key,
        visual_concept: group.visual_concept,
        ratio: assignment.ratio,
        slot: assignment.slot,
        confidence: assignment.confidence,
        evidence: assignment.evidence,
        group_confidence: group.confidence,
        group_evidence: group.evidence,
      },
    },
    binary: { data: clone(binaryData) },
  });
}

return outputs;
